impl Solution {
    pub fn lost_permutation(b: Vec<u32>, m: usize, s: u32) -> bool {
        let n = b.len() + 1;
        let mut present = vec![false; n + 1];
        for &x in &b {
            if (x as usize) <= n {
                present[x as usize] = true;
            } else {
                return false;
            }
        }

        let mut missing_sum = 0;
        for i in 1..=n {
            if !present[i] {
                missing_sum += i as u32;
            }
        }

        if missing_sum != s {
            return false;
        }

        let mut missing = Vec::new();
        for i in 1..=n {
            if !present[i] {
                missing.push(i as u32);
            }
        }

        if missing.is_empty() {
            return false;
        }

        let mut combined = b.clone();
        combined.extend(missing);
        combined.sort();

        let mut seen = std::collections::HashSet::new();
        for &x in &combined {
            if !seen.insert(x) {
                return false;
            }
        }

        if combined.len() != n {
            return false;
        }

        true
    }
}

